package cn.minidayz.patcher;
import org.json.*;import java.util.*;import java.util.regex.*;
/** Explicit version evidence only. Import time and filename are never version proof. */
public final class LogEvidence {
 static Set<String> values(String text,String keys){Set<String> found=new LinkedHashSet<String>();Pattern p=Pattern.compile("(?im)(?:^|[\\s,{])[\"']?(?:"+keys+")[\"']?\\s*[:=]\\s*(?:\"([^\"\\r\\n]+)\"|'([^'\\r\\n]+)'|([^\\r\\n,}]+))");Matcher m=p.matcher(text);while(m.find()&&found.size()<20){String v=m.group(1)!=null?m.group(1):m.group(2)!=null?m.group(2):m.group(3);if(v!=null&&v.trim().length()>0)found.add(v.trim());}return found;}
 static JSONArray array(Set<String> s){JSONArray a=new JSONArray();for(String v:s)a.put(v);return a;}
 public static JSONObject compare(String text,JSONObject selected)throws Exception{Set<String> pkg=values(text,"game_package|app_package|package_name|packageName"),version=values(text,"game_version|app_version|version_name|versionName"),hashes=values(text,"game_apk_sha256|apk_sha256|game_sha256");JSONObject evidence=new JSONObject().put("packages",array(pkg)).put("versions",array(version)).put("apk_hashes",array(hashes));boolean ambiguous=pkg.size()>1||version.size()>1||hashes.size()>1;boolean conflict=false;for(String v:pkg)if(selected.has("package")&&!v.equals(selected.optString("package")))conflict=true;for(String v:version)if(selected.has("version")&&!v.equals(selected.optString("version")))conflict=true;for(String v:hashes)if(selected.has("sha256")&&!v.equalsIgnoreCase(selected.optString("sha256")))conflict=true;boolean exact=hashes.size()==1&&selected.has("sha256")&&!conflict;boolean versionMatch=pkg.size()==1&&version.size()==1&&selected.has("package")&&selected.has("version")&&!conflict;String state=ambiguous?"ambiguous":conflict?"conflict":exact?"exact":versionMatch?"version-match":"unknown";String message=state.equals("ambiguous")?"日志含多个包名、版本或指纹，可能混入旧记录，请拆分后重新导入":state.equals("conflict")?"日志中的明确版本信息与当前APK冲突，停止自动修复":state.equals("exact")?"日志声明的APK指纹与当前文件一致（日志声明本身未认证）":state.equals("version-match")?"包名与版本字段一致，但不能证明是同一修改构建":"日志缺少可核对的明确包名、版本或APK指纹，不能自动判定归属";return new JSONObject().put("status",state).put("message",message).put("evidence",evidence).put("automatic_repair_allowed",exact||versionMatch);}
 public static JSONObject diagnose(String text)throws Exception{String[][] rules={{"NullReferenceException","空引用","结合调用栈检查对象初始化与销毁时机"},{"IndexOutOfRangeException","索引越界","核对集合长度与新增槽位、索引边界"},{"MissingMethodException","方法不匹配","核对游戏版本与插件接口，需更新适配"},{"KeyNotFoundException","键不存在","检查底层英文识别词和显示翻译是否混用"},{"OutOfMemoryError","内存不足","缩小任务或日志范围，检查资源占用"},{"SIGSEGV","原生崩溃","需要对应版本的原生库、调用栈与定位信息"},{"E_UNSUPPORTED_VERSION","缺少适配档案","生成版本差异报告，不能强行套用旧插件"},{"E_MODULE_SIGNATURE","模块签名不符","重新导入完整可信模块，不跳过签名校验"}};JSONArray groups=new JSONArray();int total=0;for(String[] rule:rules){int count=0,pos=0;while((pos=text.indexOf(rule[0],pos))>=0){count++;pos+=rule[0].length();}if(count>0){total+=count;groups.put(new JSONObject().put("signature",rule[0]).put("title",rule[1]).put("occurrences",count).put("suggestion",rule[2]).put("confidence","日志出现该标记；原因尚需代码证据"));}}return new JSONObject().put("groups",groups).put("marker_occurrences",total).put("conclusion",groups.length()==0?"未命中内置错误标记，需要查看原始日志或交AI分析":"已合并相同错误标记；仅为本地初步分类，不代表已找到或修复根因");}
}
